// Daily L1 nurture pass: (1) sync approvals from decisions tasks, (2) queue due touches 2-4,
// (3) emit approved sends for delivery. Cadence: touch N due 3 days after touch N-1 sent.
const FRAME = {"1":{"subject":"Your {artifact_name} is inside","body":"Here is your {artifact_name}. No signup wall, it is just yours.\n\nOne thing worth doing while you have it open: CTRL can build a portable context file of you in about 2 minutes. Paste it into ChatGPT or Claude and the next answer you get is about you, your company, your priorities. Not generic advice.\n\nThat part is free and takes less time than reading this email twice.\n\nBuild your context file: https://ctrl.themindmaker.ai?utm_campaign=mm_ctrl_nurture_v1&utm_source=nurture&utm_medium=email"},"2":{"subject":"You re-explain yourself to AI every day","body":"Count how many times you told an AI tool who you are this week. Your role, your company, what you are working on. Every conversation starts from zero, so every answer stays generic. That is the zero-context tax, and leaders pay it daily.\n\nCTRL ends it. Two minutes of talking builds your Memory Web. One click exports it to any AI tool you already use.\n\nIf you have not built yours yet, it is free: https://ctrl.themindmaker.ai?utm_campaign=mm_ctrl_nurture_v1&utm_source=nurture&utm_medium=email"},"3":{"subject":"What your context file is not telling you","body":"The free Memory Web tells your AI tools who you are. The Full Diagnostic tells you what you are not seeing: the tensions in how you are operating, the risks you are discounting, and the scenarios worth pressure-testing before they arrive.\n\nIt runs on the context you already built, so it is specific to your situation, not a template. One-time, $49, yours to keep.\n\nRun your Full Diagnostic: https://ctrl.themindmaker.ai?utm_campaign=mm_ctrl_nurture_v1&utm_source=nurture&utm_medium=email"},"4":{"subject":"Last note from us","body":"This is the last email in this series, so the short version:\n\nYou built your context file. The Full Diagnostic is the deep read on it: tensions, risks, scenarios, the complete thinking tools. $49 once. If the free version was useful, this is the part leaders tell us was worth paying for.\n\nEither way, we stop emailing you after this.\n\nRun the Diagnostic: https://ctrl.themindmaker.ai?utm_campaign=mm_ctrl_nurture_v1&utm_source=nurture&utm_medium=email"}};
const FOOTER = "\n\n---\nCTRL by Mindmaker. You received this because you requested an artifact at ctrl.themindmaker.ai.\nUnsubscribe: https://krishraja10101.app.n8n.cloud/webhook/ctrl-unsub?e={email}";
const SB = 'https://gojpffsrxybbpbdzzrvs.supabase.co';
const SBH = { apikey: '{{SUPABASE_SERVICE_ROLE_KEY}}', Authorization: 'Bearer {{SUPABASE_SERVICE_ROLE_KEY}}', 'Content-Type': 'application/json' };
function q(params){ const p=[]; for (const k of Object.keys(params)) p.push(encodeURIComponent(k)+'='+encodeURIComponent(params[k])); return p.join('&'); }
const now = Date.now();
const digest = { approvals_synced: 0, queued: 0, sending: 0, rejected: 0, suppressed_skips: 0 };

// 1. approval sync: queued rows whose task is done -> approved; dropped/superseded -> rejected
const queued = await this.helpers.httpRequest({ method: 'GET', url: SB + '/rest/v1/acquisition_sends?' + q({ select: 'id,approval_task_id', status: 'eq.queued', lane: 'eq.mm_ctrl' }), headers: SBH, json: true }) || [];
for (const row of queued) {
  if (!row.approval_task_id) continue;
  const t = await this.helpers.httpRequest({ method: 'GET', url: SB + '/rest/v1/tasks?' + q({ select: 'id,status', id: 'eq.' + row.approval_task_id }), headers: SBH, json: true });
  const st = (t && t[0] && t[0].status) || '';
  if (st === 'done') { await this.helpers.httpRequest({ method: 'PATCH', url: SB + '/rest/v1/acquisition_sends?id=eq.' + row.id, headers: SBH, body: { status: 'approved' }, json: true }); digest.approvals_synced++; }
  else if (st === 'superseded' || st === 'dropped') { await this.helpers.httpRequest({ method: 'PATCH', url: SB + '/rest/v1/acquisition_sends?id=eq.' + row.id, headers: SBH, body: { status: 'rejected' }, json: true }); digest.rejected++; }
}

// 2. queue due touches: last sent touch per active lead, +3 days
const sentRows = await this.helpers.httpRequest({ method: 'GET', url: SB + '/rest/v1/acquisition_sends?' + q({ select: 'lead_id,touch_number,sent_at,status,frame_version', lane: 'eq.mm_ctrl', order: 'lead_id,touch_number' }), headers: SBH, json: true }) || [];
const byLead = {};
for (const r of sentRows) { (byLead[r.lead_id] = byLead[r.lead_id] || []).push(r); }
for (const [leadId, rows] of Object.entries(byLead)) {
  const maxTouch = Math.max(...rows.map(r => r.touch_number));
  if (maxTouch >= 4) continue;
  if (rows.some(r => ['queued','approved','rejected','suppressed','failed'].includes(r.status) && r.touch_number === maxTouch)) continue;
  const last = rows.find(r => r.touch_number === maxTouch);
  if (!last || last.status !== 'sent' || !last.sent_at) continue;
  if (now - new Date(last.sent_at).getTime() < 3 * 86400000) continue;
  const leadArr = await this.helpers.httpRequest({ method: 'GET', url: SB + '/rest/v1/leads?' + q({ select: 'id,email,churned_at', id: 'eq.' + leadId }), headers: SBH, json: true });
  const lead = leadArr && leadArr[0];
  if (!lead || lead.churned_at) { digest.suppressed_skips++; continue; }
  const n = maxTouch + 1;
  const subject = FRAME[n].subject;
  const bodyTxt = FRAME[n].body + FOOTER.replace('{email}', encodeURIComponent(lead.email));
  try {
    const ins = await this.helpers.httpRequest({ method: 'POST', url: SB + '/rest/v1/acquisition_sends', headers: { ...SBH, Prefer: 'return=representation' }, body: [{ lead_id: leadId, lane: 'mm_ctrl', touch_number: n, rendered_subject: subject, rendered_body: bodyTxt, status: 'queued' }], json: true });
    const sendId = ins[0].id;
    const taskId = 'send-' + sendId;
    await this.helpers.httpRequest({ method: 'POST', url: SB + '/rest/v1/tasks', headers: SBH, body: [{ id: taskId, title: 'L1 approve: CTRL nurture touch ' + n + ' to ' + lead.email, description: 'Approved frame mm_ctrl_nurture_v1, touch ' + n + '. Mark done to send on the next scheduler pass; supersede to reject.\n\nSubject: ' + subject + '\n\n' + bodyTxt.slice(0, 1200), agent: 'cleo', status: 'waiting', workstream: 'acquisition' }], json: true });
    await this.helpers.httpRequest({ method: 'PATCH', url: SB + '/rest/v1/acquisition_sends?id=eq.' + sendId, headers: SBH, body: { approval_task_id: taskId }, json: true });
    digest.queued++;
  } catch (e) { /* unique violation = already queued */ }
}

// 3. emit approved sends
const approved = await this.helpers.httpRequest({ method: 'GET', url: SB + '/rest/v1/acquisition_sends?' + q({ select: 'id,lead_id,touch_number,rendered_subject,rendered_body,leads(email,churned_at)', status: 'eq.approved', lane: 'eq.mm_ctrl', limit: '50' }), headers: SBH, json: true }) || [];
const sends = [];
for (const r of approved) {
  const em = r.leads && r.leads.email;
  if (!em || (r.leads && r.leads.churned_at)) { await this.helpers.httpRequest({ method: 'PATCH', url: SB + '/rest/v1/acquisition_sends?id=eq.' + r.id, headers: SBH, body: { status: 'suppressed' }, json: true }); continue; }
  sends.push({ send_id: r.id, email: em, subject: r.rendered_subject, bodyTxt: r.rendered_body, touch: r.touch_number });
}
digest.sending = sends.length;
return [{ json: { digest, sends } }];
